async function generateSequentialBarcode(){if(!sb)throw Error('سجّل الدخول أولاً');const pageSize=1000;let used=new Set();for(let from=0;;from+=pageSize){const {data,error}=await sb.from('products').select('barcode').order('id',{ascending:false}).range(from,from+pageSize-1);if(error)throw error;const rows=data||[];rows.forEach(x=>{const code=String(x.barcode||'').trim();if(code)used.add(code)});if(rows.length<pageSize)break}let max=0;used.forEach(code=>{if(/^\d{6}$/.test(code))max=Math.max(max,Number(code))});let next=max+1;while(used.has(String(next).padStart(6,'0')))next++;if(next>999999)throw Error('تم الوصول إلى الحد الأقصى للباركود المتسلسل');return String(next).padStart(6,'0')}
