function matchesPeriod(dateStr,period,now){let d=new Date(dateStr);if(Number.isNaN(d.getTime()))return false;if(period==='today')return d.toDateString()===now.toDateString();if(period==='7d')return d<=now&&(now-d)<=7*86400000;if(period==='month')return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear();return true}
function renderReports(){let period=$('reportPeriod')?.value||'all',now=new Date(),a=sales.filter(s=>matchesPeriod(s.created_at,period,now));let total=a.reduce((x,s)=>x+Number(s.total||0),0),profit=a.reduce((x,s)=>x+Number(s.profit||0),0),storeExpenses=expenses.filter(e=>e.type==='متجر'&&matchesPeriod(e.created_at,period,now)).reduce((x,e)=>x+Number(e.amount||0),0),netProfit=profit-storeExpenses,qty=a.reduce((x,s)=>x+Number(s.qty||0),0),rTotal=$('rptTotal'),rProfit=$('rptProfit'),rNetProfit=$('rptNetProfit'),rQty=$('rptQty'),rAvg=$('rptAvg'),rInventoryCost=$('rptStockCost'),rPotential=$('rptStockPotential'),reportRows=$('reportRows'),label=$('reportPeriodLabel');if(rTotal)rTotal.textContent=money(total);if(rProfit)rProfit.textContent=money(profit);if(rNetProfit)rNetProfit.textContent=money(netProfit);if(rQty)rQty.textContent=qty.toLocaleString('ar-LY');if(rAvg)rAvg.textContent=money(a.length?total/a.length:0);if(rInventoryCost)rInventoryCost.textContent=money(products.reduce((x,p)=>x+Number(p.buy||0)*Number(p.qty||0),0));if(rPotential)rPotential.textContent=money(products.reduce((x,p)=>x+Number(p.sell||0)*Number(p.qty||0),0));if(label)label.textContent=period==='today'?'اليوم':period==='7d'?'آخر 7 أيام':period==='month'?'هذا الشهر':'كل المبيعات';let top={};a.forEach(s=>{let k=s.product||s.barcode||'غير معروف';top[k]=(top[k]||0)+Number(s.qty||0)});let rows=Object.entries(top).sort((x,y)=>y[1]-x[1]).slice(0,20);if(reportRows)reportRows.innerHTML=rows.length?rows.map(([k,v])=>`<tr><td>${String(k).replace(/[<>]/g,'')}</td><td>${v}</td></tr>`).join(''):`<tr><td colspan="2" class="empty">لا توجد مبيعات</td></tr>`}
