function setViewButtons(view,show){document.querySelectorAll('[data-v="'+view+'"],[data-menu-view="'+view+'"]').forEach(el=>{if(show)el.style.removeProperty('display');else el.style.setProperty('display','none','important')})}
function applyPermissionGating(){setViewButtons('users',isOwnerUser);let canPartner=partnerCanView();setViewButtons('partner',canPartner);if(!isOwnerUser){Object.entries(GATED_VIEWS).forEach(([view,sec])=>setViewButtons(view,canViewSection(sec)));setViewButtons('reports',canViewSection('sales'));let hasOther=Object.values(GATED_VIEWS).some(sec=>canViewSection(sec));if(canPartner&&!hasOther){setViewButtons('dashboard',false);document.querySelectorAll('.vp-bottom-nav').forEach(el=>el.style.setProperty('display','none','important'));showView('partner')}}if(isOwnerUser)loadStaffList()}
async function loadStaffList(){if(!isOwnerUser)return;try{let {data,error}=await sb.from('staff_permissions').select('*').order('created_at',{ascending:true});if(error)throw error;staffList=data||[];renderUsers()}catch(e){console.error(e)}}
function renderAll(){renderProducts();renderOrders();renderReturns();renderCustomers();renderReports();renderExpenses();let low=products.filter(p=>Number(p.qty||0)<=Number(p.min||0)),lowEl=$('lowStock');if(lowEl)lowEl.innerHTML=low.length?low.map(p=>`<div class="low-item"><b>${p.name}</b><span>${p.qty} متبقي</span></div>`).join(''):'<div class="empty">لا توجد تنبيهات</div>';let totalSales=sales.reduce((a,s)=>a+Number(s.total||0),0),dashSalesEl=$('dashSales'),dashProductsEl=$('dashProducts'),dashOrdersEl=$('dashOrders'),dashProfitEl=$('dashProfit');if(dashSalesEl)dashSalesEl.textContent=money(totalSales);if(dashProductsEl)dashProductsEl.textContent=products.length.toLocaleString('ar-LY');if(dashOrdersEl)dashOrdersEl.textContent=orders.length.toLocaleString('ar-LY');if(dashProfitEl)dashProfitEl.textContent=money(sales.reduce((a,s)=>a+Number(s.profit||0),0))}
async function importData(event){
  const file=event.target.files?.[0];
  if(!file)return;
  const clean=row=>{const o={};Object.keys(row||{}).forEach(k=>{if(!['id','user_id','created_at','updated_at','order_no'].includes(k))o[k]=row[k]});return o};
  const fingerprint=row=>JSON.stringify(clean(row));
  try{
    const data=JSON.parse(await file.text());
    const tables=[['products',data.products,products,true],['customers',data.customers,customers,false],['suppliers',data.suppliers,suppliers,false],['orders',data.orders,orders,false],['sales',data.sales,sales,false],['returns',data.returns,returnsRows,false],['expenses',data.expenses,expenses,false]];
    if(!tables.some(x=>Array.isArray(x[1])))throw Error('ملف النسخة الاحتياطية غير صالح');
    if(!sb)throw Error('سجّل الدخول أولاً');
    let added=0,updated=0;
    for(const [table,rows,current,isProducts] of tables){
      if(!Array.isArray(rows)||!rows.length)continue;
      if(isProducts){
        for(const original of rows){
          const row=clean(original);
          row.barcode=String(row.barcode||'').trim();
          if(!row.barcode)continue;
          const {data:up,error}=await sb.from('products').upsert(row,{onConflict:'user_id,barcode'}).select('id').maybeSingle();
          if(error)throw Error('المنتجات: '+error.message);
          if(up)updated++;
        }
      }else{
        const seen=new Set((current||[]).map(fingerprint));
        for(const original of rows){
          const row=clean(original);
          const fp=fingerprint(row);
          if(seen.has(fp))continue;
          const {error}=await sb.from(table).insert(row);
          if(error)throw Error(table+': '+error.message);
          seen.add(fp);added++;
        }
      }
    }
    await loadAll();
    toast('تم استيراد النسخة الاحتياطية بنجاح — أضيف '+added+' وتحدث '+updated);
  }catch(e){console.error(e);toast('فشل الاستيراد: '+(e.message||'ملف غير صالح'))}
  finally{event.target.value=''}
}
function exportData(){let blob=new Blob([JSON.stringify({products,sales,customers,suppliers,orders,returns:returnsRows,expenses},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='veronza-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
