const PARTNER_PERCENT=30;
let partnerMonthsReady=false,partnerSettlements=[];
function partnerMonthKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01'}
function partnerMonthLabel(key){let [y,m]=key.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('ar-LY',{year:'numeric',month:'long'})}
function fillPartnerMonths(){let sel=$('partnerMonth');if(!sel||partnerMonthsReady)return;let now=new Date(),keys=[];for(let i=0;i<12;i++)keys.push(partnerMonthKey(new Date(now.getFullYear(),now.getMonth()-i,1)));sel.innerHTML=keys.map((k,i)=>`<option value="${k}">${partnerMonthLabel(k)}${i===0?' (الجاري)':''}</option>`).join('');partnerMonthsReady=true}
async function renderPartner(){if(!sb||!partnerCanView())return;fillPartnerMonths();let key=$('partnerMonth').value,currentKey=partnerMonthKey(new Date());let {data:sets,error:setErr}=await sb.from('profit_settlements').select('*').order('period_month',{ascending:false});partnerSettlements=setErr?[]:(sets||[]);let closed=partnerSettlements.find(s=>s.period_month===key),src;if(closed){src={sales_profit:closed.sales_profit,orders_profit:closed.orders_profit,returns_profit_reversed:closed.returns_profit_reversed,store_expenses:closed.store_expenses,net_profit:closed.net_profit,orders_missing_cost:0}}else{let {data,error}=await sb.rpc('calc_month',{p_month:key});if(error)return toast('تعذر حساب الشهر: '+error.message,6000);src=Array.isArray(data)?data[0]:data;if(!src)return toast('لا توجد بيانات لهذا الشهر')}let net=Number(src.net_profit||0),percent=closed?Number(closed.partner_percent):PARTNER_PERCENT,share=closed?Number(closed.partner_share):Math.max(net,0)*percent/100;$('ptSales').textContent=money(src.sales_profit);$('ptOrders').textContent=money(src.orders_profit);$('ptReturns').textContent=money(src.returns_profit_reversed);$('ptExpenses').textContent=money(src.store_expenses);$('ptNet').textContent=money(net);$('ptShareLabel').textContent='حصة الشريك ('+percent.toLocaleString('ar-LY')+'%)';$('ptShare').textContent=money(share);let state=$('partnerState');if(state)state.textContent=closed?('🔒 مقفول — '+(closed.paid?'تم الدفع':'لم يُدفع بعد')):(key===currentKey?'الشهر الجاري — أرقام مباشرة وغير نهائية':'لم يُقفل بعد');let warn=$('partnerWarn'),missing=Number(src.orders_missing_cost||0);if(warn){warn.style.display=missing>0?'':'none';warn.textContent=missing>0?('يوجد '+missing.toLocaleString('ar-LY')+' طلب خالص بدون تكلفة (بدون باركود)، وربحه غير محسوب. راجعه قبل إقفال الشهر.'):''}let actions=$('partnerOwnerActions'),btn=$('partnerCloseBtn');if(actions)actions.style.display=(isOwnerUser&&!closed)?'':'none';if(btn)btn.disabled=key>=currentKey;let rows=$('partnerRows');if(rows)rows.innerHTML=partnerSettlements.length?partnerSettlements.map(s=>`<tr><td>${partnerMonthLabel(s.period_month)}</td><td>${money(s.net_profit)}</td><td>${Number(s.partner_percent).toLocaleString('ar-LY')}%</td><td><b>${money(s.partner_share)}</b></td><td>${s.paid?'✅ تم الدفع':'⏳ لم يُدفع'}</td><td>${isOwnerUser&&!s.paid?`<button class="gold" onclick="markPartnerPaid('${s.period_month}')">تسجيل الدفع</button>`:''}</td></tr>`).join(''):`<tr><td colspan="6" class="empty">لا توجد أشهر مقفولة بعد</td></tr>`}
async function closePartnerMonth(){if(!isOwnerUser)return;let key=$('partnerMonth').value;if(!confirm('إقفال شهر '+partnerMonthLabel(key)+' نهائيًا؟ بعد الإقفال تتثبت الأرقام وحصة الشريك، ولا يمكن إضافة أو تعديل مصروفات هذا الشهر.'))return;let {data,error}=await sb.rpc('close_month',{p_month:key,p_partner_percent:PARTNER_PERCENT});if(error)return toast(error.message,6000);toast('تم إقفال الشهر — حصة الشريك '+money(data&&data.partner_share));await renderPartner()}
async function markPartnerPaid(key){if(!isOwnerUser)return;if(!confirm('تسجيل أن حصة '+partnerMonthLabel(key)+' تم دفعها للشريك؟'))return;let {error}=await sb.rpc('mark_settlement_paid',{p_month:key});if(error)return toast(error.message,6000);toast('تم تسجيل الدفع');await renderPartner()}

