/* ===== الطلبات: صناديق مفصولة + حالة واحدة + تعديل الطلب ومنتجاته ===== */
const ORDER_BOX_TITLES={all:'كل الطلبات','تحت المراجعة':'تحت المراجعة','طلبات الشركة':'طلبات الشركة','طلبات طرابلس':'طلبات طرابلس','راجع':'راجع','ملغي':'ملغي','تم التسليم':'تم التسليم','خالص':'🔒 خالص'};
let ordersMode='list';
function orderEffectiveStatus(o){if(o.status===ORDER_LOCKED_STATUS)return ORDER_LOCKED_STATUS;if(o.status==='راجع'||o.status==='ملغي')return o.status;if(o.delivery_status==='تم التسليم'||o.status==='تم التسليم')return 'تم التسليم';return ORDER_STATUSES.includes(o.status)?o.status:'تحت المراجعة'}
function orderMatchesFilter(o,filter){return filter==='all'||orderEffectiveStatus(o)===filter}
function openOrderBox(filter){orderStatusFilter=filter||'all';ordersMode='list';const s=$('orderSearch');if(s)s.value='';showView('orders')}
function filterOrders(status){openOrderBox(status)}
function openOrderForm(id){ordersMode='form';ofStart(id);showView('orders')}
function closeOrderForm(){ordersMode='list';showView('orders')}
function applyOrdersMode(){const list=ordersMode==='list';$('orderListMode').style.display=list?'':'none';$('orderFormMode').style.display=list?'none':'';if(list)renderOrders()}
function orderCard(o,items){const st=orderEffectiveStatus(o),locked=st===ORDER_LOCKED_STATUS,digits=String(o.phone||'').replace(/[^\d+]/g,''),phone=o.phone?(digits?`<a href="tel:${digits}" dir="ltr">${escHtml(o.phone)}</a>`:escHtml(o.phone)):'—',date=o.created_at?new Date(o.created_at).toLocaleString('ar-LY',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'';let lines='';if(items.length){lines=items.slice(0,3).map(i=>`<div class="oc-line"><span>${escHtml(i.product||i.barcode)}${i.size?' · '+escHtml(i.size):''}</span><b>× ${i.qty}</b></div>`).join('')+(items.length>3?`<div class="oc-more">+${items.length-3} منتجات أخرى</div>`:'')}else if(o.barcode){const p=products.find(x=>x.barcode===o.barcode);lines=`<div class="oc-line"><span>${escHtml(p?p.name+(p.size?' · '+p.size:''):o.barcode)}</span><b>× ${o.qty||1}</b></div>`}const bookingThumb=o.booking_image?`<a class="oc-img" data-img="${escHtml(o.booking_image)}" href="#" target="_blank" rel="noopener"><img alt=""><span>📎 صورة الحجز — اضغط للتكبير</span></a>`:'';const controls=locked?'':`<div class="vc-actions"><div class="vc-field"><label>الحالة</label><select onchange="setOrderStatus(${o.id},this)">${ORDER_STATUSES.map(s=>`<option ${st===s?'selected':''}>${s}</option>`).join('')}</select></div><button onclick="openOrderForm(${o.id})">✎ تعديل</button><button class="danger" onclick="deleteOrder(${o.id})">حذف</button></div>`;return `<div class="vcard${locked?' locked':''}"><div class="vc-head"><div><div class="vc-title">${escHtml(o.customer||'بدون اسم')}</div><div class="vc-sub">طلب ${escHtml(o.order_no||'')}${date?' · '+date:''}</div></div><div class="vc-price">${money(o.total)}</div></div><div class="vc-pills">${locked?vcPill('🔒 خالص — مقفول',ORDER_STATUS_COLORS['خالص']):vcPill(st,ORDER_STATUS_COLORS[st]||DELIVERY_COLORS[st])}</div>${bookingThumb}${lines?`<div class="oc-items">${lines}</div>`:''}<div class="vc-meta"><div><span>الهاتف</span>${phone}</div><div><span>العنوان</span><b>${escHtml(o.address||'—')}</b></div>${o.notes?`<div class="wide"><span>ملاحظات</span><b>${escHtml(o.notes)}</b></div>`:''}</div>${controls}</div>`}
function renderOrders(){const filter=orderStatusFilter;let list=getOrderDisplayList().filter(o=>orderMatchesFilter(o,filter));updateOrderCounts();const byOrder={};orderItems.forEach(it=>{(byOrder[it.order_id]=byOrder[it.order_id]||[]).push(it)});const total=list.length,q=($('orderSearch')?.value||'').toLowerCase().trim();if(q)list=list.filter(o=>[o.order_no,o.customer,o.phone,o.address,o.notes,o.barcode,...(byOrder[o.id]||[]).map(i=>(i.product||'')+' '+i.barcode)].join(' ').toLowerCase().includes(q));$('orderBoxTitle').textContent=ORDER_BOX_TITLES[filter]||'الطلبات';$('orderBoxCount').textContent=(q?list.length+' من ':'')+total+' طلب';$('orderRows').innerHTML=list.length?list.map(o=>orderCard(o,byOrder[o.id]||[])).join(''):`<div class="empty">لا توجد طلبات في هذا الصندوق</div>`;hydrateOrderImages()}
async function setOrderStatus(id,sel){const o=orders.find(x=>x.id===id);if(!o)return;const v=sel.value;if(orderEffectiveStatus(o)===v)return;if(v===ORDER_LOCKED_STATUS&&!confirm('تأكيد: عند تحويل الطلب إلى "خالص" يتقفل نهائيًا، ولا يمكن تعديله أو حذفه أو إرجاعه لحالة أخرى، ويدخل في حساب حصة الشريك. هل تريد المتابعة؟')){renderOrders();return}const patch={status:v};if(v==='تم التسليم')patch.delivery_status='تم التسليم';else if(o.delivery_status==='تم التسليم')patch.delivery_status='قيد التجهيز';try{if(v===ORDER_LOCKED_STATUS){const wasDec=!!o.stock_decremented;if(!wasDec){const {error}=await sb.rpc('decrement_stock_for_order',{p_order_id:id});if(error)throw error}const {error}=await sb.from('orders').update(patch).eq('id',id);if(error){if(!wasDec)await sb.rpc('restore_stock_for_order',{p_order_id:id});throw error}}else{const {error}=await sb.from('orders').update(patch).eq('id',id);if(error)throw error;if(ORDER_STOCK_DECREMENT_STATUSES.includes(v)){const {error:e2}=await sb.rpc('decrement_stock_for_order',{p_order_id:id});if(e2)toast('تم تحديث الحالة لكن تعذر خصم المخزون: '+e2.message,6500)}else if(ORDER_STOCK_RESTORE_STATUSES.includes(v)){const {error:e2}=await sb.rpc('restore_stock_for_order',{p_order_id:id});if(e2)toast('تم تحديث الحالة لكن تعذر إرجاع المخزون: '+e2.message,6500)}}toast(v===ORDER_LOCKED_STATUS?'تم قفل الطلب — خالص':'تم تحديث الحالة: '+v)}catch(e){toast(e.message||'تعذر تحديث الحالة',6500)}await loadAll()}
async function deleteOrder(id){const o=orders.find(x=>x.id===id);if(!confirm('حذف الطلب؟'+(o&&o.stock_decremented?' سيُرجع المخزون المخصوم.':'')))return;try{if(o&&o.stock_decremented){const {error}=await sb.rpc('restore_stock_for_order',{p_order_id:id});if(error)throw error}const {error}=await sb.from('orders').delete().eq('id',id);if(error){if(o&&o.stock_decremented)await sb.rpc('decrement_stock_for_order',{p_order_id:id});throw error}toast('تم حذف الطلب')}catch(e){toast(e.message||'تعذر حذف الطلب',6000)}await loadAll()}

let ofItems=[],ofEditingId=null,ofSaving=false,ofTotalAuto=true,ofOrigQty={},ofOriginalHadItems=false;
function ofProduct(bc){return products.find(p=>p.barcode===bc)}
function ofSubtotal(){return ofItems.reduce((s,i)=>{const p=ofProduct(i.barcode);return s+(p?Number(p.sell||0)*i.qty:0)},0)}
function ofStart(id){ofEditingId=null;ofItems=[];ofOrigQty={};ofOriginalHadItems=false;ofTotalAuto=true;resetBookingImage();['oCustomer','oPhone','oAddress','oNotes','oTotal','oSearch'].forEach(k=>$(k).value='');$('oResults').innerHTML='';const o=id?orders.find(x=>x.id===id):null;let title='طلب جديد',sub='يُسجَّل تحت المراجعة تلقائيًا',btn='حفظ الطلب';if(o){ofEditingId=o.id;ofExistingImage=o.booking_image||null;title='تعديل الطلب '+(o.order_no||'');sub='';btn='حفظ التعديلات';$('oCustomer').value=o.customer||'';$('oPhone').value=o.phone||'';$('oAddress').value=o.address||'';$('oNotes').value=o.notes||'';const its=orderItems.filter(i=>i.order_id===o.id);ofItems=its.length?its.map(i=>({barcode:i.barcode,qty:Number(i.qty)})):(o.barcode?[{barcode:o.barcode,qty:Number(o.qty)||1}]:[]);ofOriginalHadItems=ofItems.length>0;if(o.stock_decremented)ofItems.forEach(i=>{ofOrigQty[i.barcode]=(ofOrigQty[i.barcode]||0)+i.qty});$('oTotal').value=o.total!=null?o.total:'';ofTotalAuto=false}$('ofTitle').textContent=title;$('ofSub').textContent=sub;$('ofSave').textContent=btn;ofShowExistingImage();ofRender()}
function ofRender(){const box=$('oItems');if(!box)return;const imgNote=$('ofImgNote');if(imgNote)imgNote.textContent=ofEditingId?((ofExistingImage||ofImageFile)?'تقدر تستبدل الصورة بصورة أخرى.':'هذا الطلب قديم وبدون صورة — تقدر تضيف له صورة.'):'الصورة إجبارية لتسجيل الطلب.';const imgStar=$('ofImgStar');if(imgStar)imgStar.style.display=ofEditingId?'none':'';const sub=ofSubtotal();let over=0;box.innerHTML=ofItems.length?ofItems.map((it,i)=>{const p=ofProduct(it.barcode),avail=p?Number(p.qty||0)+(ofOrigQty[it.barcode]||0):0,isOver=!p||it.qty>avail;if(isOver)over++;const name=p?[p.name,p.model,p.color].filter(Boolean).join(' · '):it.barcode+' (غير موجود)',price=p?Number(p.sell||0):0;return `<div class="of-item${isOver?' over':''}"><div class="of-i-info"><b>${escHtml(name)}</b><small>${p&&p.size?'مقاس '+escHtml(p.size)+' · ':''}متاح ${avail} · ${money(price)}</small></div><div class="of-qty"><button type="button" onclick="ofQty(${i},-1)">−</button><span>${it.qty}</span><button type="button" onclick="ofQty(${i},1)">+</button></div><div class="of-i-sum">${money(price*it.qty)}</div><button type="button" class="of-rm" onclick="ofRemove(${i})">✕</button></div>`}).join(''):`<div class="of-empty">لم تُضف منتجات بعد — ابحث أو امسح الباركود</div>`;$('ofSubtotal').textContent=money(sub);if(ofTotalAuto)$('oTotal').value=sub>0?sub:'';const totalVal=$('oTotal').value===''?null:Number($('oTotal').value);$('ofSync').style.display=(ofItems.length&&totalVal!==null&&Math.abs(totalVal-sub)>0.004)?'':'none';const missing=[];if(!$('oCustomer').value.trim())missing.push('اسم العميل');if(!$('oPhone').value.trim())missing.push('الهاتف');if(!ofItems.length&&!(ofEditingId&&!ofOriginalHadItems))missing.push('منتج واحد على الأقل');if(totalVal===null||!(totalVal>=0))missing.push('الإجمالي');if(!ofEditingId&&!ofImageFile)missing.push('صورة حجز الزبون');$('ofHint').textContent=missing.length?('أكمل: '+missing.join('، ')):(over?'تنبيه: كمية بعض المنتجات أكبر من المتاح في المخزون، وقد يُرفض خصمها عند تغيير الحالة.':'');$('ofSave').disabled=ofSaving||missing.length>0}
function ofTotalManual(){ofTotalAuto=false;ofRender()}
function ofSyncTotal(){ofTotalAuto=true;ofRender()}
function ofAdd(bc){const p=ofProduct(bc);if(!p)return;const ex=ofItems.find(i=>i.barcode===bc),avail=Number(p.qty||0)+(ofOrigQty[bc]||0);if(!ex&&avail<=0)return toast('هذا المقاس نفد من المخزون');if(ex)ex.qty+=1;else ofItems.push({barcode:bc,qty:1});$('oSearch').value='';$('oResults').innerHTML='';ofRender()}
function ofQty(i,d){const it=ofItems[i];if(!it)return;it.qty=Math.max(1,it.qty+d);ofRender()}
function ofRemove(i){ofItems.splice(i,1);ofRender()}
function ofMatches(q){return products.filter(p=>[p.name,p.model,p.color,p.size,p.barcode].join(' ').toLowerCase().includes(q))}
function ofSearch(){const raw=$('oSearch').value.trim(),q=raw.toLowerCase(),box=$('oResults');if(!q){box.innerHTML='';return}const exact=products.find(p=>String(p.barcode).toLowerCase()===q);if(exact){ofAdd(exact.barcode);return}const res=ofMatches(q).slice(0,8);box.innerHTML=res.length?res.map(p=>{const out=Number(p.qty||0)<=0;return `<button type="button" class="of-res${out?' out':''}" onclick="ofAdd('${escHtml(p.barcode)}')"><span><b>${escHtml([p.name,p.model,p.color].filter(Boolean).join(' · '))}</b><small>${p.size?'مقاس '+escHtml(p.size)+' · ':''}${escHtml(p.barcode)}</small></span><span><b>${money(p.sell)}</b><small>${out?'نفد':'متاح '+escHtml(p.qty)}</small></span></button>`}).join(''):`<div class="of-empty">لا توجد منتجات مطابقة</div>`}
function ofKey(e){if(e.key!=='Enter')return;e.preventDefault();const q=$('oSearch').value.trim().toLowerCase();if(!q)return;const exact=products.find(p=>String(p.barcode).toLowerCase()===q);if(exact)return ofAdd(exact.barcode);const res=ofMatches(q);if(res.length===1)ofAdd(res[0].barcode)}
function ofScan(){return startBarcodeScan('oSearch','oScanDone')}

/* ===== شاشة المستخدمين: إنشاء حساب + صلاحيات بصناديق + بطاقات ===== */
const PERMISSION_PRESETS={partner:{reports:['view']},cashier:{sales:['view','add'],returns:['view','add'],products:['view'],customers:['view','add']},orders:{orders:['view','add','edit'],products:['view'],customers:['view','add']},all:Object.fromEntries(PERMISSION_SECTIONS.map(([sec])=>[sec,sec==='reports'?['view']:['view','add','edit']])),none:{}};
function setPermBoxes(perms){PERMISSION_SECTIONS.forEach(([sec])=>{PERMISSION_ACTIONS.forEach(([act])=>{const cb=$('uPerm_'+sec+'_'+act);if(cb)cb.checked=!!(perms&&perms[sec]&&(Array.isArray(perms[sec])?perms[sec].includes(act):perms[sec][act]))})})}
function applyPreset(name){setPermBoxes(PERMISSION_PRESETS[name]||{})}
function uUpdateBtn(){const b=$('uSave');if(b)b.textContent=$('uPassword').value?'إنشاء الحساب وحفظ الصلاحيات':'حفظ الصلاحيات'}
function clearUserForm(){$('uEmail').value='';$('uPassword').value='';setPermBoxes({});$('uFormTitle').textContent='إضافة موظف أو شريك';uUpdateBtn()}
function renderUsers(){const box=$('usersContent'),denied=$('usersDenied');if(!isOwnerUser){if(box)box.style.display='none';if(denied)denied.style.display='';return}if(box)box.style.display='';if(denied)denied.style.display='none';const rows=$('staffRows');if(!rows)return;rows.innerHTML=staffList.length?staffList.map(s=>{const isOwn=s.role==='owner',tags=isOwn?'<span class="up-tag">كل الصلاحيات</span>':(Object.entries(s.permissions||{}).filter(([,v])=>v&&Object.values(v).some(Boolean)).map(([sec,v])=>{const secLabel=(PERMISSION_SECTIONS.find(x=>x[0]===sec)||[sec,sec])[1],acts=Object.entries(v).filter(([,on])=>on).map(([act])=>(PERMISSION_ACTIONS.find(x=>x[0]===act)||[act,act])[1]).join(' / ');return `<span class="up-tag">${escHtml(secLabel)}: ${escHtml(acts)}</span>`}).join('')||'<span class="up-tag none">بدون صلاحيات</span>');return `<div class="vcard"><div class="vc-head"><div><div class="vc-title" dir="ltr" style="text-align:right">${escHtml(s.email||'')}</div><div class="vc-sub">${isOwn?'المالك':'موظف'}</div></div>${isOwn?vcPill('👑 مالك',['#1b1917','#f2dfb9']):''}</div><div class="up-tags">${tags}</div>${isOwn?'':`<div class="vc-actions"><button onclick="editStaff('${escHtml(s.user_id)}')">✎ تعديل</button><button class="danger" onclick="removeStaff('${escHtml(s.user_id)}')">إزالة الصلاحيات</button></div>`}</div>`}).join(''):`<div class="empty">لا يوجد موظفون بعد</div>`}
async function saveStaffPermission(){if(!isOwnerUser)return toast('للمالك فقط');const email=$('uEmail').value.trim().toLowerCase(),password=$('uPassword').value;if(!email)return toast('اكتب البريد الإلكتروني');const perms={};PERMISSION_SECTIONS.forEach(([sec])=>{const secPerms={};PERMISSION_ACTIONS.forEach(([act])=>{const cb=$('uPerm_'+sec+'_'+act);if(cb&&cb.checked)secPerms[act]=true});if(Object.keys(secPerms).length)perms[sec]=secPerms});if(!Object.keys(perms).length&&!confirm('لم تحدد أي صلاحية، وسيبقى الحساب بلا صلاحيات. هل تريد المتابعة؟'))return;const btn=$('uSave');btn.disabled=true;try{if(password){if(password.length<6)throw Error('كلمة المرور لازم تكون 6 أحرف على الأقل');const {data,error}=await sb.functions.invoke('create-staff-user',{body:{email,password,permissions:perms}});if(error){let msg=error.message;try{const j=await error.context.json();if(j&&j.error)msg=j.error}catch(_){}throw Error(msg)}if(data&&data.error)throw Error(data.error);toast(data&&data.existed?'تم تحديث الحساب والصلاحيات':'تم إنشاء الحساب وحفظ الصلاحيات — يقدر يدخل الآن',4000)}else{const {error}=await sb.rpc('set_staff_permission',{p_email:email,p_permissions:perms});if(error)throw error;toast('تم حفظ الصلاحيات')}clearUserForm();await loadStaffList()}catch(e){toast(e.message||'تعذر الحفظ',7000)}finally{btn.disabled=false;uUpdateBtn()}}
function editStaff(userId){const s=staffList.find(x=>x.user_id===userId);if(!s)return;$('uEmail').value=s.email||'';$('uPassword').value='';setPermBoxes(s.permissions||{});$('uFormTitle').textContent='تعديل: '+(s.email||'');uUpdateBtn();window.scrollTo({top:0,behavior:'smooth'})}
async function removeStaff(userId){if(!isOwnerUser)return;if(!confirm('إزالة كل صلاحيات هذا الموظف؟ (الحساب نفسه يبقى لكن بدون أي صلاحية)'))return;const {error}=await sb.from('staff_permissions').delete().eq('user_id',userId);if(error)return toast(error.message);toast('تمت إزالة صلاحيات الموظف');await loadStaffList()}

/* ===== صورة حجز الزبون (إجبارية عند إضافة طلب) ===== */
let ofImageFile=null,ofImagePreviewUrl=null,ofExistingImage=null;
const orderImgCache=new Map();
async function signedOrderImages(paths){const now=Date.now(),need=paths.filter(p=>{const c=orderImgCache.get(p);return !c||c.exp<now+60000});if(need.length){try{const {data,error}=await sb.storage.from('order-images').createSignedUrls(need,3600);if(!error&&data)data.forEach(r=>{if(r.signedUrl)orderImgCache.set(r.path,{url:r.signedUrl,exp:now+3600*1000})})}catch(e){console.error(e)}}return paths.map(p=>(orderImgCache.get(p)||{}).url||null)}
async function hydrateOrderImages(){const links=[...document.querySelectorAll('#orderRows .oc-img[data-img]')];if(!links.length)return;const paths=[...new Set(links.map(a=>a.dataset.img))];await signedOrderImages(paths);links.forEach(a=>{const c=orderImgCache.get(a.dataset.img);if(c){a.href=c.url;const img=a.querySelector('img');if(img&&img.getAttribute('src')!==c.url)img.src=c.url}})}
function setBookingPreview(url){const img=$('ofPreview');if(url){img.src=url;img.style.display='';$('ofPhIcon').style.display='none';$('ofPhText').style.display='none';$('ofImgRemove').style.display=ofImageFile?'':'none';$('ofPhoto').classList.add('has-img')}else{img.removeAttribute('src');img.style.display='none';$('ofPhIcon').style.display='';$('ofPhText').style.display='';$('ofImgRemove').style.display='none';$('ofPhoto').classList.remove('has-img')}}
function resetBookingImage(){ofImageFile=null;ofExistingImage=null;if(ofImagePreviewUrl){URL.revokeObjectURL(ofImagePreviewUrl);ofImagePreviewUrl=null}const inp=$('oImage');if(inp)inp.value='';if($('ofPreview'))setBookingPreview(null)}
async function ofShowExistingImage(){if(!ofExistingImage||ofImageFile)return;const [url]=await signedOrderImages([ofExistingImage]);if(url&&!ofImageFile)setBookingPreview(url)}
function onBookingImage(input){const f=input.files&&input.files[0];if(!f)return;if(!/^image\//.test(f.type)){input.value='';return toast('اختر ملف صورة')}if(f.size>25*1024*1024){input.value='';return toast('الصورة كبيرة جدًا')}ofImageFile=f;if(ofImagePreviewUrl)URL.revokeObjectURL(ofImagePreviewUrl);ofImagePreviewUrl=URL.createObjectURL(f);setBookingPreview(ofImagePreviewUrl);ofRender()}
function clearBookingImage(ev){if(ev){ev.preventDefault();ev.stopPropagation()}ofImageFile=null;if(ofImagePreviewUrl){URL.revokeObjectURL(ofImagePreviewUrl);ofImagePreviewUrl=null}$('oImage').value='';setBookingPreview(null);ofShowExistingImage();ofRender()}
async function uploadOrderImage(file){const blob=await resizeProductImage(file,1600,0.85);const {data:{user}}=await sb.auth.getUser();const path=(user&&user.id||'anon')+'/'+Date.now()+'-'+Math.random().toString(36).slice(2,8)+'.jpg';const {error}=await sb.storage.from('order-images').upload(path,blob,{contentType:'image/jpeg',cacheControl:'3600'});if(error)throw Error('تعذر رفع الصورة: '+error.message);return path}
async function ofSave(){if(ofSaving)return;ofRender();if($('ofSave').disabled)return;const customer=$('oCustomer').value.trim(),phone=$('oPhone').value.trim(),address=$('oAddress').value.trim(),notes=$('oNotes').value.trim(),total=Number($('oTotal').value),items=ofItems.map(i=>({barcode:i.barcode,qty:i.qty}));ofSaving=true;$('ofSave').disabled=true;$('ofSave').textContent='جارٍ الحفظ...';let imagePath=null;try{if(ofImageFile)imagePath=await uploadOrderImage(ofImageFile);if(ofEditingId){const {error}=await sb.rpc('update_order',{p_order_id:ofEditingId,p_customer:customer,p_phone:phone,p_address:address,p_notes:notes,p_total:total,p_items:(items.length||ofOriginalHadItems)?items:null,p_booking_image:imagePath});if(error)throw error;if(imagePath&&ofExistingImage){try{await sb.storage.from('order-images').remove([ofExistingImage])}catch(_){}}toast('تم حفظ تعديلات الطلب')}else{const {data,error}=await sb.rpc('create_order',{p_customer:customer,p_phone:phone,p_address:address,p_notes:notes,p_total:total,p_items:items,p_booking_image:imagePath});if(error)throw error;orderStatusFilter='تحت المراجعة';toast('تمت إضافة الطلب رقم '+(data&&data.order_no||'')+' — تحت المراجعة',3500)}ordersMode='list';ofSaving=false;showView('orders');await loadAll()}catch(e){if(imagePath){try{await sb.storage.from('order-images').remove([imagePath])}catch(_){}}toast('تعذر الحفظ: '+(e.message||'خطأ غير معروف'),6500)}finally{ofSaving=false;$('ofSave').textContent=ofEditingId?'حفظ التعديلات':'حفظ الطلب';ofRender()}}
